package com.cliprecorder;

import lombok.Value;

/**
 * A single frame in the rolling buffer: either a JPEG-compressed image, or a
 * zero-byte "repeat previous frame" marker (jpeg == null) used when the screen
 * barely changed - those cost nothing on disk or in memory.
 */
@Value
class Frame
{
	byte[] jpeg;
	long timestampMs;
	int width;
	int height;

	boolean isRepeat()
	{
		return jpeg == null;
	}

	int byteSize()
	{
		return jpeg == null ? 0 : jpeg.length;
	}
}

package com.cliprecorder;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

/**
 * Bounded ring buffer of JPEG frames. Bounded both by frame count and by total
 * bytes so a mis-configured capture can never balloon memory.
 */
class FrameRingBuffer
{
	private final ArrayDeque<Frame> frames = new ArrayDeque<>();
	private final int maxFrames;
	private final long maxBytes;
	private long totalBytes;

	FrameRingBuffer(int maxFrames, long maxBytes)
	{
		this.maxFrames = maxFrames;
		this.maxBytes = maxBytes;
	}

	synchronized void add(Frame frame)
	{
		frames.addLast(frame);
		totalBytes += frame.byteSize();
		while (frames.size() > maxFrames || totalBytes > maxBytes)
		{
			totalBytes -= frames.removeFirst().byteSize();
		}
	}

	/**
	 * Copy out all frames whose timestamp falls within [fromMs, toMs].
	 */
	synchronized List<Frame> snapshot(long fromMs, long toMs)
	{
		List<Frame> out = new ArrayList<>();
		for (Frame f : frames)
		{
			if (f.getTimestampMs() >= fromMs && f.getTimestampMs() <= toMs)
			{
				out.add(f);
			}
		}
		return out;
	}

	synchronized void clear()
	{
		frames.clear();
		totalBytes = 0;
	}

	synchronized long getTotalBytes()
	{
		return totalBytes;
	}

	synchronized int size()
	{
		return frames.size();
	}
}

package com.cliprecorder;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.MemoryCacheImageOutputStream;

/**
 * Downscales captured frames and compresses them to JPEG using javax.imageio
 * (no external dependencies). Not thread-safe; confine to one executor thread.
 */
class JpegEncoder
{
	/**
	 * @param maxHeight scale down to this height if taller; 0 = no scaling
	 * @return scaled frame as JPEG bytes, or null on encode failure
	 */
	byte[] encode(Image image, int maxHeight, float quality, int[] dimsOut) throws IOException
	{
		int srcW = image.getWidth(null);
		int srcH = image.getHeight(null);
		if (srcW <= 0 || srcH <= 0)
		{
			return null;
		}

		int w = srcW;
		int h = srcH;
		if (maxHeight > 0 && h > maxHeight)
		{
			w = Math.max(1, (int) Math.round((double) srcW * maxHeight / srcH));
			h = maxHeight;
		}
		// MJPEG decoders behave best with even dimensions
		w &= ~1;
		h &= ~1;
		if (w == 0 || h == 0)
		{
			return null;
		}

		// 3BYTE_BGR is the JPEG writer's native layout - it compresses this
		// directly instead of converting the pixels first
		BufferedImage rgb = new BufferedImage(w, h, BufferedImage.TYPE_3BYTE_BGR);
		Graphics2D g = rgb.createGraphics();
		try
		{
			if (w == srcW && h == srcH)
			{
				g.drawImage(image, 0, 0, null); // plain copy, no scaling pass
			}
			else
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.drawImage(image, 0, 0, w, h, null);
			}
		}
		finally
		{
			g.dispose();
		}

		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
		try
		{
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(quality);

			ByteArrayOutputStream bos = new ByteArrayOutputStream(128 * 1024);
			try (MemoryCacheImageOutputStream mos = new MemoryCacheImageOutputStream(bos))
			{
				writer.setOutput(mos);
				writer.write(null, new IIOImage(rgb, null, null), param);
			}
			dimsOut[0] = w;
			dimsOut[1] = h;
			return bos.toByteArray();
		}
		finally
		{
			writer.dispose();
		}
	}
}

package com.cliprecorder;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.List;

/**
 * Minimal MJPEG-in-AVI muxer, pure Java, no dependencies.
 *
 * Every frame is already a complete JPEG, so writing a clip is just wrapping
 * the frames in RIFF/AVI chunk headers plus an idx1 index. All chunk sizes are
 * known up front, so the file is written in a single streaming pass.
 */
final class MjpegAviWriter
{
	private static final int AVIF_HASINDEX = 0x10;
	private static final int AVIIF_KEYFRAME = 0x10;

	private MjpegAviWriter()
	{
	}

	/**
	 * Write frames to an AVI file. All frames must share the dimensions of the
	 * provided width/height; callers filter beforehand.
	 */
	static void write(File file, List<Frame> frames, int fps, int width, int height) throws IOException
	{
		if (frames.isEmpty())
		{
			throw new IOException("No frames to write");
		}

		final int n = frames.size();

		// movi chunk payload: each frame is '00dc' + int32 size + data + pad-to-even;
		// repeat markers are zero-length chunks (standard AVI "repeat last frame")
		long moviDataSize = 0;
		for (Frame f : frames)
		{
			moviDataSize += 8 + f.byteSize() + (f.byteSize() & 1);
		}
		final long moviListSize = 4 + moviDataSize; // 'movi' fourcc + chunks
		final long idxSize = 16L * n;

		// hdrl: 'hdrl' + avih chunk (8+56) + LIST strl (8 + 4 + strh(8+56) + strf(8+40))
		final int strlListSize = 4 + 64 + 48;
		final int hdrlListSize = 4 + 64 + 8 + strlListSize;

		final long riffSize = 4 // 'AVI '
			+ 8 + hdrlListSize
			+ 8 + moviListSize
			+ 8 + idxSize;

		int maxFrameBytes = 0;
		for (Frame f : frames)
		{
			maxFrameBytes = Math.max(maxFrameBytes, f.byteSize());
		}

		try (OutputStream out = new BufferedOutputStream(new FileOutputStream(file), 1 << 16))
		{
			fourcc(out, "RIFF");
			u32(out, riffSize);
			fourcc(out, "AVI ");

			// ---- LIST hdrl ----
			fourcc(out, "LIST");
			u32(out, hdrlListSize);
			fourcc(out, "hdrl");

			// avih - main AVI header
			fourcc(out, "avih");
			u32(out, 56);
			u32(out, 1_000_000L / fps); // dwMicroSecPerFrame
			u32(out, (long) maxFrameBytes * fps); // dwMaxBytesPerSec
			u32(out, 0); // dwPaddingGranularity
			u32(out, AVIF_HASINDEX); // dwFlags
			u32(out, n); // dwTotalFrames
			u32(out, 0); // dwInitialFrames
			u32(out, 1); // dwStreams
			u32(out, maxFrameBytes); // dwSuggestedBufferSize
			u32(out, width);
			u32(out, height);
			u32(out, 0); // dwReserved[4]
			u32(out, 0);
			u32(out, 0);
			u32(out, 0);

			// ---- LIST strl ----
			fourcc(out, "LIST");
			u32(out, strlListSize);
			fourcc(out, "strl");

			// strh - stream header
			fourcc(out, "strh");
			u32(out, 56);
			fourcc(out, "vids");
			fourcc(out, "MJPG");
			u32(out, 0); // dwFlags
			u32(out, 0); // wPriority + wLanguage
			u32(out, 0); // dwInitialFrames
			u32(out, 1); // dwScale
			u32(out, fps); // dwRate -> fps = rate/scale
			u32(out, 0); // dwStart
			u32(out, n); // dwLength (frames)
			u32(out, maxFrameBytes); // dwSuggestedBufferSize
			u32(out, 0xFFFFFFFFL); // dwQuality (-1 = default)
			u32(out, 0); // dwSampleSize
			u16(out, 0); // rcFrame left
			u16(out, 0); // rcFrame top
			u16(out, width); // rcFrame right
			u16(out, height); // rcFrame bottom

			// strf - BITMAPINFOHEADER
			fourcc(out, "strf");
			u32(out, 40);
			u32(out, 40); // biSize
			u32(out, width);
			u32(out, height);
			u16(out, 1); // biPlanes
			u16(out, 24); // biBitCount
			fourcc(out, "MJPG"); // biCompression
			u32(out, (long) width * height * 3); // biSizeImage
			u32(out, 0); // biXPelsPerMeter
			u32(out, 0); // biYPelsPerMeter
			u32(out, 0); // biClrUsed
			u32(out, 0); // biClrImportant

			// ---- LIST movi ----
			fourcc(out, "LIST");
			u32(out, moviListSize);
			fourcc(out, "movi");

			for (Frame f : frames)
			{
				fourcc(out, "00dc");
				u32(out, f.byteSize());
				if (!f.isRepeat())
				{
					out.write(f.getJpeg());
					if ((f.byteSize() & 1) != 0)
					{
						out.write(0);
					}
				}
			}

			// ---- idx1 ----
			fourcc(out, "idx1");
			u32(out, idxSize);
			long offset = 4; // relative to start of 'movi' fourcc
			for (Frame f : frames)
			{
				fourcc(out, "00dc");
				u32(out, f.isRepeat() ? 0 : AVIIF_KEYFRAME);
				u32(out, offset);
				u32(out, f.byteSize());
				offset += 8 + f.byteSize() + (f.byteSize() & 1);
			}
		}
	}

	private static void fourcc(OutputStream out, String s) throws IOException
	{
		for (int i = 0; i < 4; i++)
		{
			out.write(s.charAt(i));
		}
	}

	private static void u32(OutputStream out, long v) throws IOException
	{
		out.write((int) (v & 0xFF));
		out.write((int) ((v >> 8) & 0xFF));
		out.write((int) ((v >> 16) & 0xFF));
		out.write((int) ((v >> 24) & 0xFF));
	}

	private static void u16(OutputStream out, int v) throws IOException
	{
		out.write(v & 0xFF);
		out.write((v >> 8) & 0xFF);
	}
}

